#!/usr/bin/env python3
from pathlib import Path
import os
import re
import sys

app_gradle = Path("android/app/build.gradle")
if not app_gradle.is_file():
    print("ERROR: android/app/build.gradle was not generated by Capacitor.", file=sys.stderr)
    raise SystemExit(1)

version_name = os.environ.get("VERSION_NAME", "").strip()
version_code = os.environ.get("VERSION_CODE", "").strip()

if not version_name or not version_code:
    print("ERROR: VERSION_NAME and VERSION_CODE are required.", file=sys.stderr)
    raise SystemExit(1)

text = app_gradle.read_text(encoding="utf-8")

text, namespace_count = re.subn(
    r'(?m)^\s*namespace\s*=\s*"[^"]+"',
    '    namespace = "com.sevenx.anime"',
    text,
    count=1,
)
if namespace_count != 1:
    print("ERROR: could not locate the generated Android namespace.", file=sys.stderr)
    raise SystemExit(1)

text, app_id_count = re.subn(
    r'(?m)^\s*applicationId\s+"[^"]+"',
    '        applicationId "com.sevenx.anime"',
    text,
    count=1,
)
if app_id_count != 1:
    print("ERROR: could not locate the generated Android applicationId.", file=sys.stderr)
    raise SystemExit(1)

text, code_count = re.subn(
    r'(?m)^\s*versionCode\s+\d+',
    f'        versionCode {version_code}',
    text,
    count=1,
)
if code_count != 1:
    print("ERROR: could not locate the generated Android versionCode.", file=sys.stderr)
    raise SystemExit(1)

text, name_count = re.subn(
    r'(?m)^\s*versionName\s+"[^"]+"',
    f'        versionName "{version_name}"',
    text,
    count=1,
)
if name_count != 1:
    print("ERROR: could not locate the generated Android versionName.", file=sys.stderr)
    raise SystemExit(1)

if 'applicationIdSuffix ".debug"' not in text:
    marker = "    buildTypes {"
    debug_block = """    buildTypes {
        debug {
            applicationIdSuffix ".debug"
            debuggable true
        }
"""
    if marker not in text:
        print("ERROR: could not locate Android buildTypes block.", file=sys.stderr)
        raise SystemExit(1)
    text = text.replace(marker, debug_block, 1)

app_id_match = re.search(r'applicationId\s+"([^"]+)"', text)
namespace_match = re.search(r'namespace\s*=\s*"([^"]+)"', text)
if not app_id_match or app_id_match.group(1) != "com.sevenx.anime":
    print("ERROR: production applicationId was not configured as expected.", file=sys.stderr)
    raise SystemExit(1)
if not namespace_match or namespace_match.group(1) != "com.sevenx.anime":
    print("ERROR: Android namespace was not configured as expected.", file=sys.stderr)
    raise SystemExit(1)

app_gradle.write_text(text, encoding="utf-8")

strings = Path("android/app/src/main/res/values/strings.xml")
if strings.is_file():
    source_strings = strings.read_text(encoding="utf-8")
    source_strings, _ = re.subn(
        r'(<string name="app_name">).*?(</string>)',
        r'\g<1>7xAnime\g<2>',
        source_strings,
        count=1,
    )
    source_strings, _ = re.subn(
        r'(<string name="title_activity_main">).*?(</string>)',
        r'\g<1>7xAnime\g<2>',
        source_strings,
        count=1,
    )
    source_strings, _ = re.subn(
        r'(<string name="package_name">).*?(</string>)',
        r'\g<1>com.sevenx.anime\g<2>',
        source_strings,
        count=1,
    )
    source_strings, _ = re.subn(
        r'(<string name="custom_url_scheme">).*?(</string>)',
        r'\g<1>com.sevenx.anime\g<2>',
        source_strings,
        count=1,
    )
    strings.write_text(source_strings, encoding="utf-8")

debug_strings = Path("android/app/src/debug/res/values/strings.xml")
debug_strings.parent.mkdir(parents=True, exist_ok=True)
debug_strings.write_text(
    '''<?xml version="1.0" encoding="utf-8"?>
<resources>
    <string name="app_name">7xAnime Debug</string>
    <string name="title_activity_main">7xAnime Debug</string>
</resources>
''',
    encoding="utf-8",
)


# Generate launcher artwork from the repository's source-of-truth SVGs.
# CairoSVG is installed explicitly by the Android build workflow.
try:
    import cairosvg
except ImportError as exc:
    print("ERROR: CairoSVG is required to generate branded Android launcher icons.", file=sys.stderr)
    raise SystemExit(1) from exc

brand_dir = Path("public/brand")
brand_mark = brand_dir / "7xanime-mark.svg"
brand_foreground = brand_dir / "7xanime-foreground.svg"
brand_monochrome = brand_dir / "7xanime-monochrome.svg"
for source in (brand_mark, brand_foreground, brand_monochrome):
    if not source.is_file():
        print(f"ERROR: missing 7xAnime brand asset: {source}", file=sys.stderr)
        raise SystemExit(1)

resource_root = Path("android/app/src/main/res")
density_specs = [
    ("mdpi", 48, 108),
    ("hdpi", 72, 162),
    ("xhdpi", 96, 216),
    ("xxhdpi", 144, 324),
    ("xxxhdpi", 192, 432),
]
for density, legacy_size, adaptive_size in density_specs:
    output_dir = resource_root / f"mipmap-{density}"
    output_dir.mkdir(parents=True, exist_ok=True)
    for icon_name in ("ic_launcher", "ic_launcher_round"):
        cairosvg.svg2png(
            url=str(brand_mark),
            write_to=str(output_dir / f"{icon_name}.png"),
            output_width=legacy_size,
            output_height=legacy_size,
        )
    for icon_name, source in (
        ("ic_launcher_foreground", brand_foreground),
        ("ic_launcher_monochrome", brand_monochrome),
    ):
        cairosvg.svg2png(
            url=str(source),
            write_to=str(output_dir / f"{icon_name}.png"),
            output_width=adaptive_size,
            output_height=adaptive_size,
        )

colors_file = resource_root / "values" / "colors.xml"
colors_file.parent.mkdir(parents=True, exist_ok=True)
if colors_file.is_file():
    colors_text = colors_file.read_text(encoding="utf-8")
else:
    colors_text = '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n</resources>\n'
if re.search(r'<color name="brand_background">.*?</color>', colors_text):
    colors_text = re.sub(
        r'<color name="brand_background">.*?</color>',
        '<color name="brand_background">#09090F</color>',
        colors_text,
        count=1,
    )
else:
    colors_text = colors_text.replace(
        "</resources>",
        '    <color name="brand_background">#09090F</color>\n</resources>',
        1,
    )
colors_file.write_text(colors_text, encoding="utf-8")

adaptive_icon_dir = resource_root / "mipmap-anydpi-v26"
adaptive_icon_dir.mkdir(parents=True, exist_ok=True)
adaptive_icon = '''<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@color/brand_background" />
    <foreground android:drawable="@mipmap/ic_launcher_foreground" />
    <monochrome android:drawable="@mipmap/ic_launcher_monochrome" />
</adaptive-icon>
'''
(adaptive_icon_dir / "ic_launcher.xml").write_text(adaptive_icon, encoding="utf-8")
(adaptive_icon_dir / "ic_launcher_round.xml").write_text(adaptive_icon, encoding="utf-8")

print(f"Configured com.sevenx.anime version {version_name} ({version_code}) with a separate debug id com.sevenx.anime.debug.")
